from format_lecon import Lesson,paras,steps,table
from diagnostics import comparison
from medicaments import xylometazoline
l=Lesson('Écoulement nasal')
l.add('L’écoulement nasal, ou rhinorrhée, peut être antérieur ou postérieur. Sa {description clinique} oriente le bilan. Un symptôme fréquent peut néanmoins révéler une cause urgente lorsqu’il est inhabituel ou associé à des signes de gravité.',paras('Préciser caractère aqueux, muqueux, purulent ou sanglant, côté atteint, durée et circonstances. Un écoulement vers le pharynx peut s’accompagner de gêne ou de toux, sans prouver à lui seul une maladie des sinus.', 'La couleur seule n’identifie pas un agent infectieux. Une rhinorrhée claire n’est pas toujours allergique, et une sécrétion colorée n’impose pas automatiquement un antibiotique.'),(1,2,3,4,6,7,8))
l.add('Le {contexte est souvent viral, allergique ou inflammatoire}. L’âge, les expositions et la chronologie changent la probabilité des causes. Les dix diagnostics présentés sont une sélection pédagogique, sans classement suisse de fréquence inventé.',paras('Chez l’enfant, un écoulement unilatéral fétide fait particulièrement rechercher un corps étranger. Chez l’adulte, des symptômes unilatéraux persistants ou sanglants justifient un examen spécialisé ; une présentation bilatérale habituelle n’a pas le même niveau d’alerte.', 'La sélection n’épuise pas les causes : origine dentaire, infection spécifique, maladie inflammatoire systémique, anomalies de clairance mucociliaire ou effet d’un médicament peuvent nécessiter une enquête ciblée.'),(1,3,4,5,6,8))
an=l.subwindow('anatomie','Muqueuse, sinus et barrière crânienne',paras('Les cornets portent une muqueuse vascularisée qui participe au conditionnement de l’air. Les sécrétions et leur transport vers le pharynx contribuent à éliminer des particules ; inflammation et œdème modifient cet équilibre.', 'Les sinus communiquent avec les fosses nasales par leurs orifices de drainage. Une inflammation nasosinusienne peut gêner ce drainage et produire obstruction, écoulement et pression faciale ; ces symptômes ne prouvent pas automatiquement une infection bactérienne.', 'Dans l’allergie, l’exposition déclenche une réaction médiée par les IgE avec libération de médiateurs dont l’histamine. Dans d’autres rhinites, irritants ou réflexes neurovégétatifs peuvent provoquer les symptômes sans allergie systémique démontrée.', 'La base du crâne sépare les espaces intracrâniens des cavités nasosinusiennes. Une brèche peut permettre une fuite de liquide cérébrospinal, mécanisme distinct de l’hypersécrétion d’une rhinite.'),(1,4,7))
l.add('Les {bases anatomiques et inflammatoires} expliquent la diversité des écoulements. La muqueuse, les voies de drainage et les médiateurs n’interviennent pas de la même manière dans chaque cause. Une fuite de liquide cérébrospinal relève d’une rupture de barrière.',paras(an),(1,4,7))
l.add('Les {urgences} sont recherchées avant le traitement symptomatique. Atteinte visuelle, signes neurologiques ou état général sévère imposent une évaluation immédiate. Une pile bouton nasale ou une suspicion de fuite après traumatisme ne doit pas attendre un essai de spray.',table(['🚩 Présentation','Action'],[['Baisse visuelle, œil déplacé, diplopie, limitation oculomotrice, œdème orbital important.','Urgence hospitalière pour complication orbitaire ou autre lésion.'],['Céphalée sévère, méningisme, trouble de conscience, déficit, sepsis.','Urgence immédiate ; 144 si détresse ou urgence neurologique.'],['Pile bouton ou aimants comprimant la cloison.','Extraction urgente par une équipe équipée, sans attente à domicile.'],['Écoulement aqueux inhabituel après traumatisme ou chirurgie, suspicion de brèche.','Évaluation urgente spécialisée ; ne pas retarder pour un traitement de rhume.'],['Écoulement sanglant ou obstruction unilatérale persistante avec douleur, masse ou déficit.','Avis ORL rapide ; urgence immédiate si menace visuelle ou neurologique.']]),(3,4,5,6,7,8))
l.add('L’{anamnèse précise temps, côté et déclencheurs}. Elle recherche symptômes oculaires, respiratoires, faciaux et neurologiques. Les médicaments déjà utilisés font partie du diagnostic.',paras('Distinguer début récent avec contexte viral, persistance sans amélioration, aggravation après une amélioration et épisodes liés à une exposition. Demander prurit, éternuements, odorat, fièvre, douleur dentaire, toux, sifflements et retentissement sur sommeil et activités.', 'Interroger sur traumatisme, chirurgie nasale ou de la base du crâne, insertion possible d’objet, travail exposé à des poussières et traitements décongestionnants répétés. Un écoulement aqueux unilatéral variant avec la posture mérite une attention particulière ; il ne prouve toutefois pas à lui seul une brèche.'),(1,3,4,5,6,7,8))
l.add('L’{examen est nasal et général}. Il apprécie état clinique, muqueuse, sécrétions et éventuelle masse ou corps étranger. Les yeux, le visage, la bouche et la respiration sont examinés selon les signes associés.',paras('La rhinoscopie antérieure peut montrer sécrétions, obstruction, lésion ou objet. Une endoscopie spécialisée est utile si l’origine reste inexpliquée ou la présentation atypique. Ne pas multiplier les gestes aveugles dans un nez saignant ou suspect de contenir un objet.', 'Rechercher troubles visuels ou oculomoteurs, œdème facial, douleur dentaire et signes neurologiques si contexte. Devant une rhinite allergique probable, évaluer aussi un éventuel asthme ; devant une détresse, le bilan nasal passe après la stabilisation.'),(1,3,5,6,7,8))
l.add('Le {tableau différentiel} organise les principales causes retenues. La durée et la latéralité orientent, mais aucun signe isolé ne suffit. Les diagnostics peuvent coexister.',comparison(),(1,2,3,4,5,6,7,8))
l.add('Le {diagnostic positif dépend du syndrome}. Rhume, allergie, rhinosinusite et fuite liquidienne ne partagent pas les mêmes critères. Les durées aident à classer sans remplacer la recherche des signes de gravité.',paras('Dans EPOS2020, la rhinosinusite associe au moins deux symptômes, dont obstruction ou écoulement, avec éventuellement douleur/pression faciale et baisse de l’odorat. La forme virale habituelle dure moins de dix jours ; une aggravation après cinq jours ou une persistance au-delà de dix jours oriente vers une forme postvirale, qui n’est pas synonyme de bactérienne.', 'La suspicion bactérienne repose sur un faisceau de signes : écoulement coloré à prédominance unilatérale, douleur locale importante souvent unilatérale, fièvre supérieure à 38 °C, inflammation biologique si mesurée et aggravation secondaire. EPOS retient au moins trois critères ; cela n’impose pas des analyses à tous les patients.', 'La rhinosinusite chronique suppose des symptômes pendant au moins douze semaines, avec confirmation objective par endoscopie ou imagerie selon l’évaluation spécialisée. Les formes avec polypes bilatéraux sont distinguées des formes sans polypes ; une masse unilatérale atypique demande un autre bilan.', 'Une allergie exige une histoire compatible : un test de sensibilisation positif seul ne prouve pas la responsabilité de l’allergène. Une fuite de liquide cérébrospinal est confirmée par analyse adaptée du liquide et localisée par l’imagerie.'),(1,3,4,7))
l.add('Les {examens sont ciblés}. Une rhinorrhée banale ou une rhinosinusite aiguë simple ne justifie pas automatiquement scanner, culture ou prise de sang. Une présentation compliquée, persistante ou atypique change cette conduite.',table(['Question','Examen et limite'],[['Allergie responsable ?','Tests cutanés ou IgE spécifiques si utiles, interprétés avec l’exposition et les symptômes.'],['Maladie chronique ou masse ?','Endoscopie puis imagerie adaptée ; prélèvement tumoral organisé après évaluation radiologique.'],['Complication orbitocrânienne ?','Bilan hospitalier urgent et imagerie selon les équipes.'],['Fuite liquidienne ?','Bêta-2-transferrine ou bêta-trace selon laboratoire, puis scanner ciblé et/ou IRM ; avis spécialisé.'],['Corps étranger ?','Localisation visuelle ou endoscopique ; radiologie selon nature et question, pas de manipulation aveugle.'],['Origine dentaire ?','Examen buccodentaire et bilan dirigé.']]),(1,3,4,5,6,7,8))
l.add('L’{algorithme} commence par les dangers et les causes focales. Il distingue ensuite tableaux aigus, récurrents et chroniques. Toute aggravation ou absence d’évolution attendue entraîne une réévaluation.',steps('Chercher urgence visuelle, neurologique, infectieuse sévère, pile bouton ou contexte de brèche.', 'Caractériser côté, aspect, chronologie, expositions et médicaments.', 'Orienter vers rhinite, rhinosinusite, corps étranger, fuite ou masse, puis choisir les examens réellement utiles.', 'Traiter la cause ou les symptômes selon l’indication et les limites de la préparation.', 'Fixer le suivi et les signes imposant une consultation anticipée.'),(1,3,4,5,6,7,8))
med=xylometazoline(l)
l.add('La {prise en charge suisse} associe soins adaptés et traitement de la cause. Les antibiotiques sont réservés aux indications retenues après évaluation. Un décongestionnant peut soulager brièvement une obstruction, mais son usage prolongé peut entretenir les symptômes.',paras('Pour les formes habituelles, les soins salins peuvent aider selon tolérance et âge. Pour préparer un lavage, utiliser une solution adaptée et une eau préalablement bouillie puis refroidie selon les consignes du dispositif, avec matériel propre ; ne pas utiliser directement l’eau du robinet non traitée.', 'L’allergie peut nécessiter corticoïde nasal ou antihistaminique selon les symptômes et la situation. Vérifier indication, âge, technique et terrain de la spécialité ; les traitements de fond ne remplacent pas le bilan d’un écoulement atypique.',med,'Une pile bouton nécessite une extraction urgente. Une brèche ou une masse relève d’une équipe spécialisée. Ne pas retarder ces orientations par des traitements symptomatiques répétés ; les schémas antimicrobiens et interventions dépendent du diagnostic.'),(1,2,3,4,5,7,8,9,12))
l.add('La {prévention et le suivi} réduisent expositions évitables et erreurs de traitement. La technique du spray et l’entretien du matériel comptent. Une gêne persistante doit conduire à revoir le diagnostic et l’observance.',paras('Réduire fumée et irritants, adapter les mesures d’éviction à une allergie cliniquement pertinente et garder piles et petits objets hors de portée des enfants. Éviter le renouvellement automatique d’un vasoconstricteur nasal.', 'Faire consulter sans attendre devant baisse visuelle, gonflement orbitaire, trouble neurologique, céphalée intense ou état général altéré. Des symptômes unilatéraux persistants, sanglants ou inexpliqués nécessitent un avis spécialisé, même sans fièvre.', 'Les lavages et sprays après chirurgie suivent les consignes opératoires. Une suspicion de fuite liquidienne demande un avis spécifique plutôt qu’un lavage ou une instrumentation improvisés.'),(1,3,4,5,6,7,8,9,12))
l.add('Le {point essentiel} est de relier l’écoulement à son contexte. La couleur seule ne justifie pas un antibiotique. Unilatéralité persistante, signes de gravité et exposition médicamenteuse changent la conduite.',paras('Une présentation fréquente n’autorise pas à ignorer un signe inhabituel. Les symptômes, le retentissement et l’évolution guident le suivi autant que l’étiquette diagnostique initiale.'),(1,3,4,5,7,8))
l.quiz([
('Un écoulement vert prouve-t-il une infection bactérienne ?','Non, la couleur isolée ne suffit pas.'),
('Quels éléments décrivent la rhinorrhée ?','Aspect, côté, durée, contexte et symptômes associés.'),
('Que suggère un écoulement unilatéral fétide chez un enfant ?','Un corps étranger doit être recherché.'),
('Une pile bouton nasale peut-elle attendre le lendemain ?','Non, elle expose à une nécrose rapide et doit être extraite en urgence.'),
('Quels signes oculaires rendent une sinusite urgente ?','Baisse visuelle, diplopie, déplacement de l’œil ou trouble oculomoteur, notamment avec œdème.'),
('Un écoulement clair après traumatisme doit-il être traité comme une allergie sans bilan ?','Non, rechercher une fuite de liquide cérébrospinal.'),
('Postviral signifie-t-il forcément bactérien ?','Non.'),
('Quel délai définit la chronicité selon EPOS ?','Au moins douze semaines de symptômes, avec confirmation objective adaptée.'),
('Un test allergique positif suffit-il à désigner la cause ?','Non, il doit correspondre à l’histoire clinique.'),
('Un scanner est-il nécessaire pour tout rhume ?','Non.'),
('Pourquoi demander la durée d’utilisation d’un spray vasoconstricteur ?','Une utilisation prolongée peut entretenir une rhinite médicamenteuse.'),
('Spray et gouttes de xylométazoline ont-ils forcément la même posologie ?','Non, vérifier forme, concentration, âge et notice suisse.'),
('Peut-on préparer un lavage avec de l’eau du robinet non traitée ?','Non, suivre les consignes d’eau sûre, notamment bouillie puis refroidie.'),
('Que faire de symptômes unilatéraux persistants ou sanglants ?','Organiser un bilan ORL, sans multiplier des traitements empiriques prolongés.')
],(1,3,4,5,6,7,8,9,12))
l.write()
